1	#!/usr/bin/env bun
2	/**
3	 * notify_unattended.ts — tell a person that a pull request's validation finished
4	 * and nobody was dispatched.
5	 *
6	 * ## Why this is a step of its own
7	 *
8	 * The validation writes a check run and, when it can, dispatches an agent. When it
9	 * cannot, the check is still written and the work simply waits -- and a pull
10	 * request that waits unannounced is the failure this exists to prevent. It is the
11	 * same failure `unattendedNotice` covers at creation time, one round later: the
12	 * pull request was attended when it was opened, and the agent it named is not
13	 * coming -- the verdicts that reach here are red results, a deliverable that
14	 * cannot start a run, a run that never reported a conclusion, and green results
15	 * whose ball sits with a person or behind a thread that could not be read.
16	 *
17	 * A run that is already WORKING never reaches here: the workflow gates this step
18	 * on the validation's `unattended` output, which is `false` when the hold says a
19	 * run is in flight or the chain carries the call. There the running agent's own
20	 * report is the thread's next word, and an unattended notice would invite a
21	 * person to start a run that has already started (#546).
22	 *
23	 * ## Who is told
24	 *
25	 * `resolveNotify`, which is the person who asked for the run -- the commenter for a
26	 * comment, the opener for an issue, and the repository owner as a last resort. It
27	 * is the same resolution every other notice uses, so a person who is told about a
28	 * failure here is the person who was told about the run starting.
29	 *
30	 * Usage:
31	 *   notify_unattended.ts --repo OWNER/REPO --number N --summary "..."
32	 */
33	import { parseArgs } from "node:util";
34	import { gh } from "../../adapters/github/gh.ts";
35	import { resolveNotify } from "../../adapters/github/notify.ts";
36	import { LLM_CONTEXT_TAG } from "../../adapters/github/tags.ts";
37	import { mentionPrefix } from "../../domain/work/mention.ts";
38	import { defineScript } from "./lib/script-ref.ts";
39	
40	export interface NotifyUnattendedArgs {
41	  repo: string;
42	  number: string | number;
43	  summary: string;
44	}
45	
46	export const ref = defineScript<NotifyUnattendedArgs>(import.meta.url);
47	
48	function main(): void {
49	  const { values } = parseArgs({
50	    args: Bun.argv.slice(2),
51	    options: {
52	      repo: { type: "string" },
53	      number: { type: "string" },
54	      summary: { type: "string" },
55	    },
56	  });
57	
58	  const repo = values.repo ?? "";
59	  const number = values.number ?? "";
60	  if (!repo || !number) {
61	    console.error("usage: notify_unattended.ts --repo OWNER/REPO --number N --summary \"...\"");
62	    process.exit(2);
63	  }
64	
65	  const notify = resolveNotify(repo, Number(number));
66	  const mention = mentionPrefix(notify);
67	  const summary = (values.summary ?? "").trim();
68	
69	  // Tagged `include`, deliberately. This is a fact about the pull request -- that
70	  // its validation finished and nobody is coming -- and a later agent reading the
71	  // thread should see it. The bookkeeping comments are the ones that are excluded.
72	  const body = [
73	    LLM_CONTEXT_TAG.write("include"),
74	    `${mention}Atomaton: validation of this pull request finished and no agent was dispatched.`,
75	    ...(summary ? ["", summary] : []),
76	    "",
77	    "Comment `/<agent>` on this pull request to start one, or merge it yourself.",
78	  ].join("\n");
79	
80	  const posted = gh("pr", "comment", String(number), "--repo", repo, "--body", body);
81	  if (posted.code) {
82	    console.error(`::warning::could not post the unattended notice on #${number}: ${posted.stderr.trim()}`);
83	  }
84	}
85	
86	if (import.meta.main) main();

